// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.28;

import {ICouncilManager} from "./interfaces/council/ICouncilManager.sol";
import {IDkgResultsAdapter} from "./interfaces/IDkgResultsAdapter.sol";
import {DAVINCITypes} from "./libraries/DAVINCITypes.sol";

/**
 * @title CouncilAdapter
 * @notice The registry's seam to a Council manager (invite-only threshold DKG): it binds
 *         each COUNCIL-mode process to the ceremony its DKGParams name, hands the ceremony
 *         key to the registry, submits the final accumulator as one decryption request and
 *         reads the combined plaintexts back. Created by the ProcessRegistry constructor, so
 *         `registry` is fixed to its creator. A ceremony's organizer must allow this adapter
 *         and authorize the process creator on the manager before a process can bind.
 *         Results wait for the ceremony's decryption gate, which the registry reads through
 *         isDecryptionOpen.
 * @dev Council stores and returns circomlib (TE) points, the registry's form, so unlike
 *      DavinciDKGAdapter nothing is converted. The registry stores the request id as the
 *      process's dkgAid; the manager keys requests by the process id, which this adapter
 *      maps back.
 */
contract CouncilAdapter is IDkgResultsAdapter {
    /// @notice A bound process: its ceremony, the number of fields submitted (0 until the
    ///         request) and the registry process id.
    struct Binding {
        bytes12 ceremonyId;
        uint8 fieldCount;
        bytes31 processId;
    }

    /// @notice The ProcessRegistry that created this adapter; the only allowed caller of
    ///         the state-changing functions.
    address public immutable registry;
    /// @notice The Council manager (ceremonies, bindings, requests, combines).
    ICouncilManager public immutable manager;
    /// @notice Bindings by request id.
    mapping(bytes32 requestId => Binding) public bindings;

    error NotRegistry();
    /// @dev Selector-identical to IProcessRegistry.InvalidKeyMode and InvalidDKGParams, so
    ///      the revert decodes against the registry ABI when it bubbles out of newProcess.
    error InvalidKeyMode();
    error InvalidDKGParams();
    /// @notice Council has no organizer secret to reveal.
    error UnsupportedKeyMode();
    /// @notice No request was submitted under this request id and ceremony.
    error UnknownRequest();
    /// @notice The manager answered for a different request.
    error RequestMismatch();
    /// @notice plaintexts covers whole requests only: first == 0, count == fieldCount.
    error InvalidFieldRange();

    modifier onlyRegistry() {
        if (msg.sender != registry) revert NotRegistry();
        _;
    }

    constructor(address councilManager) {
        registry = msg.sender;
        manager = ICouncilManager(councilManager);
    }

    /// @notice Binds `processId`, created by `creator`, to the ceremony in `dkg.epochId` and
    ///         returns that ceremony id, the request id and the ceremony key in TE. The
    ///         manager requires a Live ceremony, this adapter allowed and `creator`
    ///         authorized.
    function register(bytes31 processId, address creator, DAVINCITypes.DKGParams calldata dkg)
        external
        onlyRegistry
        returns (bytes12 cid, bytes32 requestId, uint256 pkX, uint256 pkY)
    {
        if (dkg.mode != DAVINCITypes.KeyMode.COUNCIL) revert InvalidKeyMode();
        cid = dkg.epochId;
        if (
            cid == bytes12(0) || dkg.orgPKx != 0 || dkg.orgPKy != 0 || dkg.popAx != 0 || dkg.popAy != 0 || dkg.popZ != 0
        ) revert InvalidDKGParams();
        (requestId, pkX, pkY) = manager.bindProcess(cid, processId, creator);
        bindings[requestId] = Binding({ceremonyId: cid, fieldCount: 0, processId: processId});
    }

    /// @notice Submits the active ciphertexts (TE, [c1x, c1y, c2x, c2y] each) of the process
    ///         bound under `requestId` as one request. Council numbers fields within the
    ///         request, so the first index is always 0.
    function submit(bytes12 cid, bytes32 requestId, uint256[4][] calldata cts)
        external
        onlyRegistry
        returns (uint16 firstIndex)
    {
        Binding storage b = bindings[requestId];
        bytes31 processId = b.processId;
        if (processId == bytes31(0) || b.ceremonyId != cid) revert UnknownRequest();
        // The registry submits at most 16 fields (numFields); the manager rejects more.
        b.fieldCount = uint8(cts.length);
        if (manager.submitRequest(cid, processId, cts) != requestId) revert RequestMismatch();
        return 0;
    }

    /// @notice The combined plaintexts of the request, in field order. Only the whole
    ///         request can be read (first == 0, count == its field count), and ready is
    ///         false until every field is combined, so the registry never finalizes a
    ///         partial vector.
    function plaintexts(bytes12 cid, bytes32 requestId, uint16 first, uint16 count)
        external
        view
        returns (bool ready, uint256[] memory values)
    {
        Binding memory b = bindings[requestId];
        if (b.fieldCount == 0 || b.ceremonyId != cid) revert UnknownRequest();
        if (first != 0 || count != b.fieldCount) revert InvalidFieldRange();
        (ready, values) = manager.getPlaintexts(requestId);
        if (ready && values.length != count) revert RequestMismatch();
    }

    /// @notice Whether ceremony `cid` has opened decryption (the manager's gate, Council
    ///         protocol §8.7). The registry asks before it publishes any result of a COUNCIL
    ///         process, the all-zero vector included.
    function isDecryptionOpen(bytes12 cid) external view returns (bool) {
        return manager.isDecryptionOpen(cid);
    }

    /// @notice Council processes have no organizer key; always reverts.
    function reveal(bytes12, bytes32, uint256) external pure {
        revert UnsupportedKeyMode();
    }
}

src/DavinciDKGAdapter.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.28;

import {IDKGManager} from "./interfaces/dkg/IDKGManager.sol";
import {IDKGAppManager} from "./interfaces/dkg/IDKGAppManager.sol";
import {DKGTypes} from "./interfaces/dkg/DKGTypes.sol";
import {DAVINCITypes} from "./libraries/DAVINCITypes.sol";
import {BjjFormLib} from "./libraries/BjjFormLib.sol";

/**
 * @title DavinciDKGAdapter
 * @notice The registry's seam to the davinci-dkg contracts: it registers one DKG
 *         application per DKG-mode process, is its sole ciphertext submitter, converts
 *         BabyJubJub points between the circomlib form (DAVINCI) and the reduced form
 *         (DKG), and reads combined plaintexts back. Created by the ProcessRegistry
 *         constructor, so `registry` is fixed to its creator.
 */
contract DavinciDKGAdapter {
    /// @notice The ProcessRegistry that created this adapter; the only allowed caller
    ///         of the state-changing functions.
    address public immutable registry;
    /// @notice The davinci-dkg manager (epochs, pool keys, ciphertexts, combines).
    IDKGManager public immutable manager;
    /// @notice The davinci-dkg application manager (registration, organizer reveal).
    IDKGAppManager public immutable appManager;

    /// @dev MAX_K in the DKG: pool keys per epoch.
    uint8 private constant MAX_POOL_KEYS = 16;
    /// @dev How many epochs registrationEpoch scans backwards from the newest.
    uint64 private constant EPOCH_SCAN = 8;

    error NotRegistry();
    error NoLiveEpoch();
    error NonContiguousIndex();

    modifier onlyRegistry() {
        if (msg.sender != registry) revert NotRegistry();
        _;
    }

    constructor(address dkgManager) {
        registry = msg.sender;
        manager = IDKGManager(dkgManager);
        appManager = IDKGAppManager(IDKGManager(dkgManager).appManager());
    }

    /// @notice The DKG application id of a process, `salt << 160 | address(this)` with
    ///         salt the top 92 bits of keccak(chainid, registry, pid). The DKG only lets an
    ///         account register ids whose low 160 bits are its own address, so these ids
    ///         are this adapter's alone: nobody can take a process's id ahead of it. Never
    ///         0 and below 2^252 < Q; deterministic and collision-free across registries.
    function aidFor(bytes31 processId) public view returns (bytes32) {
        uint256 salt = uint256(keccak256(abi.encode(block.chainid, registry, processId))) >> 164;
        return bytes32((salt << 160) | uint256(uint160(address(this))));
    }

    /// @notice The newest Live epoch with a free pool key, scanning backwards at most
    ///         EPOCH_SCAN epochs from the manager's newest. Reverts NoLiveEpoch when
    ///         none qualifies.
    function registrationEpoch() public view returns (bytes12) {
        uint64 nonce = manager.epochNonce();
        uint96 prefix = uint96(manager.EPOCH_PREFIX()) << 64;
        for (uint64 i = 0; i < EPOCH_SCAN && nonce > i; ++i) {
            bytes12 eid = bytes12(prefix | uint96(nonce - i));
            uint8 next = manager.getPoolStatus(eid);
            if (next >= MAX_POOL_KEYS) continue; // pool spent
            // getPoolKey reverts InvalidPhase unless the epoch is Live.
            try manager.getPoolKey(eid, next) returns (uint256, uint256) {
                return eid;
            } catch {}
        }
        revert NoLiveEpoch();
    }

    /// @notice Registers the DKG application of `processId` and returns its epoch, aid
    ///         and encryption key `PK_aid` converted to circomlib form. LOCKED mode uses
    ///         the caller-chosen epoch (the Schnorr PoP binds it); AUTOMATIC picks
    ///         registrationEpoch().
    function register(bytes31 processId, DAVINCITypes.DKGParams calldata dkg)
        external
        onlyRegistry
        returns (bytes12 eid, bytes32 aid, uint256 teX, uint256 teY)
    {
        aid = aidFor(processId);
        bool locked = dkg.mode == DAVINCITypes.KeyMode.DKG_LOCKED;
        eid = locked ? dkg.epochId : registrationEpoch();

        address[] memory submitters = new address[](1);
        submitters[0] = address(this);
        DKGTypes.AppPolicy memory policy = DKGTypes.AppPolicy({
            mode: locked ? DKGTypes.AppMode.OrganizerLocked : DKGTypes.AppMode.Automatic,
            openSubmission: false,
            submitters: submitters,
            maxCiphertexts: 16,
            notBeforeBlock: 0,
            notAfterBlock: 0,
            decryptNotBefore: 0,
            decryptNotAfter: 0
        });
        appManager.registerApplication(eid, aid, policy, dkg.orgPKx, dkg.orgPKy, dkg.popAx, dkg.popAy, dkg.popZ);

        (uint256 rx, uint256 ry) = appManager.getApplicationKey(eid, aid);
        teX = BjjFormLib.toTE(rx);
        teY = ry;
    }

    /// @notice Submits ElGamal ciphertexts (circomlib coordinates, [c1x, c1y, c2x, c2y]
    ///         each) to the DKG, converting to the reduced form. Returns the on-chain
    ///         index of the first one and requires the rest to follow contiguously:
    ///         finalize reads [first, first + count), so a gap would silently map the
    ///         wrong plaintexts to fields.
    function submit(bytes12 eid, bytes32 aid, uint256[4][] calldata ciphertextsTE)
        external
        onlyRegistry
        returns (uint16 firstIndex)
    {
        for (uint256 i = 0; i < ciphertextsTE.length; ++i) {
            uint256[4] calldata ct = ciphertextsTE[i];
            uint16 idx =
                manager.submitCiphertext(eid, aid, BjjFormLib.toRTE(ct[0]), ct[1], BjjFormLib.toRTE(ct[2]), ct[3]);
            if (i == 0) firstIndex = idx;
            else if (idx != firstIndex + i) revert NonContiguousIndex();
        }
    }

    /// @notice Combined plaintexts of ciphertexts [first, first + count). ready is false
    ///         (and values incomplete) until every one has a completed combine.
    function plaintexts(bytes12 eid, bytes32 aid, uint16 first, uint16 count)
        external
        view
        returns (bool ready, uint256[] memory values)
    {
        values = new uint256[](count);
        for (uint16 i = 0; i < count; ++i) {
            DKGTypes.CombinedDecryptionRecord memory rec = manager.getCombinedDecryption(eid, aid, first + i);
            if (!rec.completed) return (false, values);
            values[i] = rec.plaintext;
        }
        ready = true;
    }

    /// @notice Forwards an organizer-secret reveal for a locked application. The DKG
    ///         checks sk·G == PK_org.
    function reveal(bytes12 eid, bytes32 aid, uint256 sk) external onlyRegistry {
        appManager.revealOrganizerSecret(eid, aid, sk);
    }
}

src/interfaces/council/ICouncilManager.s.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity >=0.8.4 <0.9.0;

/// @title ICouncilManager
/// @notice The CouncilManager (protocol v2) surface a DAVINCI `CouncilAdapter` uses (architecture
///         §3.1). Self-contained on purpose: copy this file verbatim into another repository.
///
///         Flow: the organizer allows the adapter and authorizes the process creator for a `Live`
///         ceremony; the adapter `bindProcess`es a process (receiving the request id and the
///         ceremony key `P`), later `submitRequest`s the process's final accumulator, and polls
///         `getPlaintexts` until `ready`. Results are produced only once the ceremony's decryption
///         gate is open (`isDecryptionOpen`, protocol §8.7): the registry must consult it before
///         publishing any result for a Council process, the all-zero fast path included.
///
///         Points are circomlib twisted Edwards (TE) `(x, y)` pairs, each `< p` (BN254 scalar
///         field); `cts[k] = [C1.x, C1.y, C2.x, C2.y]`.
interface ICouncilManager {
    /// @notice Bind `processId` to ceremony `cid`. `msg.sender` must be an allowed adapter of the
    ///         ceremony and `creator` an authorized creator; the ceremony must be `Live`; one
    ///         binding per `(msg.sender, processId)`, ever.
    /// @return requestId keccak256(abi.encode(keccak256("davinci-dkg-council/v1/request"), chainId, manager,
    ///         cid, adapter, processId)) (protocol §4.5).
    /// @return pkX ceremony public key `P`, TE x.
    /// @return pkY ceremony public key `P`, TE y.
    function bindProcess(bytes12 cid, bytes31 processId, address creator)
        external
        returns (bytes32 requestId, uint256 pkX, uint256 pkY);

    /// @notice Submit the decryption request of a bound process, once. Called by the same adapter
    ///         that bound it; `cid` is cross-checked against the binding record. 1..16 fields,
    ///         every C1/C2 canonical, on curve, in the prime subgroup and not the identity.
    ///         Admission is independent of the decryption gate.
    function submitRequest(bytes12 cid, bytes31 processId, uint256[4][] calldata cts)
        external
        returns (bytes32 requestId);

    /// @notice Combined plaintexts of a submitted request. `values.length == fieldCount`;
    ///         `ready` is true only once every field is combined (uncombined fields read 0).
    function getPlaintexts(bytes32 requestId) external view returns (bool ready, uint256[] memory values);

    /// @notice Request record. `fieldCount == 0` means bound but not yet submitted.
    function getRequestMeta(bytes32 requestId)
        external
        view
        returns (bytes12 cid, uint8 fieldCount, uint16 completedBitmap, uint16 partialBitmap);

    /// @notice Binding record of `(adapter, processId)`.
    function getBinding(address adapter, bytes31 processId)
        external
        view
        returns (bytes12 cid, bytes32 requestId, bool requested);

    /// @notice Ceremony public key `P` in TE; reverts unless the ceremony is `Live`.
    function getPublicKey(bytes12 cid) external view returns (uint256 x, uint256 y);

    /// @notice protocol §8.7 decryption gate of ceremony `cid` at `block.timestamp`: `Live` and
    ///         (Scheduled and past `decryptionOpenAt`, or Manual and opened by the organizer or past
    ///         its fallback date). Irreversible once true. Reverts for an unknown ceremony.
    function isDecryptionOpen(bytes12 cid) external view returns (bool);
}

