// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.28;

/**
 * @title ICouncilManagerErrors
 * @notice The CouncilManager errors a call through the CouncilAdapter can bubble up, declared
 *         exactly as vocdoni/davinci-dkg-council `solidity/src/CouncilTypes.sol` declares them.
 *         `ICouncilManager.sol` (verbatim upstream) carries no errors, so this interface
 *         gives clients their names: bindProcess (UnknownCeremony, WrongPhase,
 *         NotAllowedAdapter, NotAuthorizedCreator, AlreadyBound), submitRequest (UnknownCeremony,
 *         UnknownBinding, WrongPhase, AlreadyRequested, BadFieldCount, and the per-point
 *         NonCanonical, InvalidPoint, NotInSubgroup), getPlaintexts (UnknownRequest) and
 *         isDecryptionOpen (UnknownCeremony). DecryptionNotOpen is the manager's gate error
 *         (submitPartial, combine, publishPartialData); the registry reverts with the same
 *         selector (IProcessRegistry.DecryptionNotOpen) when a COUNCIL process's results are
 *         finalized before its ceremony opens decryption.
 */
interface ICouncilManagerErrors {
    error UnknownCeremony();
    error WrongPhase();
    error NotAllowedAdapter();
    error NotAuthorizedCreator();
    error AlreadyBound();
    error UnknownBinding();
    error AlreadyRequested();
    error BadFieldCount();
    error NonCanonical();
    error InvalidPoint();
    error NotInSubgroup();
    error UnknownRequest();
    error DecryptionNotOpen();
}

src/interfaces/dkg/DKGTypes.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.28;

/**
 * @title DKGTypes
 * @notice Vendored subset of davinci-dkg `src/libraries/DKGTypes.sol` (commit 2338d8a):
 *         only the types the DAVINCI adapter needs, ABI-identical to upstream.
 */
library DKGTypes {
    struct Point {
        uint256 x;
        uint256 y;
    }

    /// @notice How an application's ciphertexts get decrypted. `OrganizerLocked`
    ///         adds an organizer key (`PK_aid = P_j + PK_org`) that must be
    ///         revealed before the committee can combine; `Automatic` uses the
    ///         pool key alone (`PK_aid = P_j`).
    enum AppMode {
        OrganizerLocked,
        Automatic
    }

    /// @notice Per-application policy, fixed at registration. Submission windows
    ///         are in blocks, decryption windows in unix seconds; 0 = no bound.
    struct AppPolicy {
        AppMode mode;
        bool openSubmission; // anyone may submitCiphertext
        address[] submitters; // allow-list; empty = the registrant only
        uint16 maxCiphertexts; // 0 = unlimited (capped by MAX_CIPHERTEXT_INDEX)
        uint64 notBeforeBlock; // submitCiphertext window (blocks)
        uint64 notAfterBlock;
        uint64 decryptNotBefore; // unix seconds (0 = none)
        uint64 decryptNotAfter; // unix seconds (0 = none)
    }

    /// @notice On-chain application record, as returned by `getApplication`.
    struct Application {
        address creator;
        Point organizerPK; // (0, 1) when Automatic
        uint256 organizerSecret; // 0 while sealed and always when Automatic
        uint8 poolIndex;
        AppPolicy policy;
        uint64 createdAtBlock;
        bool exists;
    }

    struct CombinedDecryptionRecord {
        uint16 ciphertextIndex;
        bool completed;
        uint256 plaintext;
    }
}

src/interfaces/dkg/IDKGAppManager.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.28;

import {DKGTypes} from "./DKGTypes.sol";

/**
 * @title IDKGAppManager
 * @notice Vendored subset of davinci-dkg `src/interfaces/IDKGAppManager.sol`. ABI-identical to upstream.
 */
interface IDKGAppManager {
    error InvalidApplication();
    error ApplicationAlreadyExists();
    error InvalidSchnorrProof();
    error PointNotInSubgroup();
    error InvalidEpoch();
    error InvalidPhase();
    error InvalidOrganizerSecret();
    error InvalidPolicy();
    error AlreadyRevealed();
    error PoolExhausted();

    /// @notice Register an application against a Live epoch and claim the epoch's
    ///         next pool key. In `OrganizerLocked` mode the Schnorr PoP proves
    ///         knowledge of `sk_org` and `PK_aid = P_j + PK_org`; in `Automatic`
    ///         mode the key and Schnorr arguments are ignored and `PK_aid = P_j`.
    ///         Organizer key and PoP are in the DKG's reduced (a = -1) form.
    function registerApplication(
        bytes12 epochId,
        bytes32 aid,
        DKGTypes.AppPolicy calldata policy,
        uint256 pkOrgX,
        uint256 pkOrgY,
        uint256 schnorrAx,
        uint256 schnorrAy,
        uint256 schnorrZ
    ) external;

    /// @notice Publish `sk_org` for an `OrganizerLocked` application, once.
    ///         Permissionless — the contract checks `sk·G == PK_org`.
    function revealOrganizerSecret(bytes12 epochId, bytes32 aid, uint256 organizerSecret) external;

    function getApplication(bytes12 epochId, bytes32 aid) external view returns (DKGTypes.Application memory);

    /// @notice `PK_aid` of a registered application in reduced form: `P_j` for
    ///         `Automatic`, `P_j + PK_org` for `OrganizerLocked`. Reverts
    ///         `InvalidApplication` for an unknown aid.
    function getApplicationKey(bytes12 epochId, bytes32 aid) external view returns (uint256 x, uint256 y);

    /// @notice `PK_org` of a registered application — `(0, 1)` for Automatic ones,
    ///         zero for an unknown aid.
    function getOrganizerPK(bytes12 epochId, bytes32 aid) external view returns (uint256, uint256);
}

src/interfaces/dkg/IDKGManager.sol.content:
// SPDX-License-Identifier: AGPL-3.0-or-later
pragma solidity ^0.8.28;

import {DKGTypes} from "./DKGTypes.sol";

/**
 * @title IDKGManager
 * @notice Vendored subset of davinci-dkg `src/interfaces/IDKGManager.sol` (commit 2338d8a),
 *         plus the public state getters (`appManager`, `epochNonce`, `EPOCH_PREFIX`) the
 *         adapter reads from `DKGManager`. ABI-identical to upstream.
 */
interface IDKGManager {
    error InvalidEpoch();
    error InvalidPhase();
    error InvalidProofInput();
    error InvalidCiphertext();
    error CiphertextAlreadySubmitted();
    error DecryptionLimitReached();
    error PoolExhausted();
    error Unauthorized();

    /// @notice The sibling DKGAppManager (public state variable on DKGManager).
    function appManager() external view returns (address);

    /// @notice Nonce of the newest epoch; epoch ids are
    ///         `bytes12((uint96(EPOCH_PREFIX) << 64) | nonce)` (DKGIdLib.computeEpochId).
    function epochNonce() external view returns (uint64);

    /// @notice The manager's epoch-id prefix (public immutable on DKGManager).
    // solhint-disable-next-line func-name-mixedcase
    function EPOCH_PREFIX() external view returns (uint32);

    /// @notice Submit a ciphertext for threshold decryption under `PK_aid`. The
    ///         index is assigned on chain (1, 2, ... per application) and returned.
    ///         Coordinates must be canonical, on-curve and non-identity.
    function submitCiphertext(bytes12 epochId, bytes32 aid, uint256 c1x, uint256 c1y, uint256 c2x, uint256 c2y)
        external
        returns (uint16 ciphertextIndex);

    function getCombinedDecryption(bytes12 epochId, bytes32 aid, uint16 ciphertextIndex)
        external
        view
        returns (DKGTypes.CombinedDecryptionRecord memory);

    /// @notice The pool key `P_j` of a Live epoch. Reverts `InvalidPhase` before the
    ///         epoch is Live and `InvalidProofInput` for `keyIndex >= MAX_K`.
    function getPoolKey(bytes12 epochId, uint8 keyIndex) external view returns (uint256 x, uint256 y);

    /// @notice `nextIndex` is the pool key the next registration claims
    ///         (`MAX_K` once the pool is spent). Plain mapping read, never reverts.
    function getPoolStatus(bytes12 epochId) external view returns (uint8 nextIndex);

    /// @notice The pool key claimed by `aid`. Reverts `InvalidProofInput` when the
    ///         application never claimed one.
    function getAppPoolIndex(bytes12 epochId, bytes32 aid) external view returns (uint8);
}

